import React from 'react';
import { useRive, Layout, Fit } from 'rive-react';

interface AnimationProps {
  outer: boolean;
  onlySuggestions: boolean;
  success: boolean;
  warning: boolean;
}

const Animation: React.FC<AnimationProps> = ({ outer, onlySuggestions, success, warning }) => {
  const { rive, RiveComponent } = useRive({
    src: 'assets/smart_check.riv',
    autoplay: true,
  });

  // Update the animation based on boolean inputs
  React.useEffect(() => {
    if (rive) {
      rive.setInput('Outer', outer);
      rive.setInput('OnlySuggestions', onlySuggestions);
      rive.setInput('Success', success);
      rive.setInput('Warning', warning);
    }
  }, [rive, outer, onlySuggestions, success, warning]);

  return (
    <RiveComponent
      style={{ width: '100%', height: '100%' }}
      layout={Layout.Fit}
      fit={Fit.Contain}
    />
  );
};

export default Animation;
